const items = $input.all();
const output = [];

for (const item of items) {
  const json = item.json || {};
  const binary = item.binary || {};
  const binaryEntries = Object.entries(binary);

  // No binary attachment found
  if (binaryEntries.length === 0) {
    output.push({
      json: {
        ...json,
        file_detected: false,
        file_type: "unsupported",
        error: "No binary attachment found",
      },
    });
    continue;
  }

  for (const [binaryKey, file] of binaryEntries) {
    const fileName = (file.fileName || binaryKey).toLowerCase();
    const mimeType = (file.mimeType || "").toLowerCase();
    const extension = (
      file.fileExtension ||
      fileName.split(".").pop() ||
      ""
    ).toLowerCase();

    let fileType = "unsupported";

    if (
      extension === "pdf" ||
      mimeType === "application/pdf"
    ) {
      fileType = "pdf";
    } else if (
      extension === "xlsx" ||
      mimeType ===
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    ) {
      fileType = "xlsx";
    } else if (
      extension === "xls" ||
      mimeType === "application/vnd.ms-excel"
    ) {
      fileType = "xls";
    }

    output.push({
      json: {
        ...json,
        file_detected: true,
        binary_property: binaryKey,
        file_name: file.fileName || binaryKey,
        mime_type: mimeType,
        file_extension: extension,
        file_type: fileType,
        is_pdf: fileType === "pdf",
        is_excel: fileType === "xlsx" || fileType === "xls",
        supported: ["pdf", "xlsx", "xls"].includes(fileType),
      },
      binary: {
        [binaryKey]: file,
      },
    });
  }
}

return output;

const inputItems = $input.all();
const outputItems = [];

const columns = [
  "evidence_id",
  "case_id",
  "document_id",
  "filename",
  "evidence_type",
  "evidence_summary",
  "extracted_text",
  "person_or_entity",
  "event_date",
  "source_location",
  "relevance_to_case",
  "evidence_strength",
  "contradiction_flag",
  "related_evidence_ids",
  "verification_status",
  "lawyer_notes",
];

for (const item of inputItems) {
  let data = item.json.output ?? item.json;

  // Parse the AI Agent's JSON string
  if (typeof data === "string") {
    data = data.trim()
      .replace(/^```(?:json)?\s*/i, "")
      .replace(/\s*```$/, "");

    try {
      data = JSON.parse(data);
    } catch (error) {
      throw new Error(
        "Could not parse AI Agent output as JSON: " +
        error.message
      );
    }
  }

  // Handle an output object containing another JSON string
  if (typeof data.output === "string") {
    data = JSON.parse(data.output);
  }

  const records = data.evidence_records;

  if (!Array.isArray(records)) {
    throw new Error(
      "AI Agent output does not contain an evidence_records array."
    );
  }

  // Create one n8n item for every evidence record
  for (const record of records) {
    const row = {};

    for (const column of columns) {
      let value = record[column];

      if (value === undefined || value === null) {
        value = "";
      }

      // Google Sheets cell: store related IDs as text
      if (
        column === "related_evidence_ids" &&
        Array.isArray(value)
      ) {
        value = value.join(", ");
      }

      row[column] = value;
    }

    outputItems.push({ json: row });
  }
}

return outputItems;

