return sourceItems.map((item, index) => {
  if (!item.binary || Object.keys(item.binary).length === 0) {
    throw new Error(
      `Item ${index + 1} from Code in JavaScript1 has no binary file.`
    );
  }

  return {
    json: {
      ...item.json,
      has_binary: true,
      binary_properties: Object.keys(item.binary),
    },
    binary: item.binary,
