const items = $input.all();

if (items.length === 0) {
  throw new Error("No data received from Extract from File1.");
}

// Combine all extracted Excel rows into one array.
const rows = items.map((item, index) => ({
  row_number: index + 1,
  ...item.json,
}));

// Create one consolidated text representation for the AI Agent.
const documentText = rows
  .map(row =>
    Object.entries(row)
      .filter(([key, value]) =>
        key !== "row_number" &&
        value !== null &&
        value !== undefined &&
        String(value).trim() !== ""
      )
      .map(([key, value]) => `${key}: ${value}`)
      .join("\n")
  )
  .filter(text => text.trim() !== "")
  .join("\n\n");

return [
  {
    json: {
      source_node: "Extract from File1",
      original_item_count: items.length,
      row_count: rows.length,
      document_text: documentText,
      extracted_rows: rows,
    },
  },
];
